"""Renders the documents that are derived from feature.yaml and stage.yaml.

Nothing here is ever edited by hand: change the yaml and regenerate. The output is
deterministic, so "is it stale" is simply "does the file differ from a fresh render".
"""
import os

from . import flow
from . import schema as S
from .validate import blocking_bugs

HEADER = (
    "<!-- GENERATED by `qa/scripts/sdlc generate` from feature.yaml and stage.yaml. "
    "Do not edit by hand. -->\n"
)


def _list(value):
    return value if isinstance(value, list) else []


def _stages_of(bundle, feature):
    stages = [s for s in bundle["stages"] if s.get("_feature_dir") == feature["_dir"]]
    return sorted(stages, key=lambda s: (s.get("sequence") or 0, s.get("id") or ""))


def _row(*cells):
    return "| " + " | ".join(str(c) for c in cells) + " |"


def _stage_qa(stage):
    """A stage has a QA result of its own only when the owner asked for a stage pass."""
    status = stage.get("qa_status")
    return "-" if status == "not-run" else status


def _passed_qa(stage, features):
    """True when the stage was proved by QA: by its own pass, or by its feature's."""
    if stage.get("qa_status") == "pass":
        return True
    return any(f.get("_dir") == stage.get("_feature_dir") and f.get("qa_status") == "pass" for f in features)


def _turn(pair):
    role, action = pair
    if role == "-":
        return "-"
    if role == "waiting":
        return action
    return f"**{role}**: `{action}`"


def render_portfolio(bundle):
    lines = [HEADER, "# Feature portfolio", ""]
    lines += [
        "The session entry point. One row per feature, in delivery order; `Next` names the role whose",
        "turn it is and the lifecycle command to run. Milestones are explained in `docs/ROADMAP.md`;",
        "requirement detail is in `qa/coverage.md`.",
        "",
        _row("ID", "Feature", "Milestone", "Status", "Stages done", "Requirements", "Next"),
        _row("---", "---", "---", "---", "---", "---", "---"),
    ]
    in_flight = []
    for feature in bundle["features"]:
        stages = _stages_of(bundle, feature)
        done = sum(1 for s in stages if s.get("status") in S.CLAIMED)
        link = f"[{feature.get('title')}]({os.path.basename(feature['_dir'])}/)"
        lines.append(_row(
            feature.get("id"), link, feature.get("milestone"), feature.get("status"),
            f"{done}/{len(stages)}" if stages else "-",
            len(_list(feature.get("requirements"))),
            _turn(flow.feature_turn(feature, stages, bundle["features"])),
        ))
        if feature.get("status") in ("planned", "in-progress", "in-qa"):
            in_flight.append((feature, stages))

    lines += ["", "## In flight", ""]
    if not in_flight:
        lines += ["No feature is in flight.", ""]
    for feature, stages in in_flight:
        lines += [
            f"### {feature.get('id')} {feature.get('title')}", "",
            _row("Stage", "Title", "Surfaces", "Status", "Stage QA", "Blocking bugs", "Next"),
            _row("---", "---", "---", "---", "---", "---", "---"),
        ]
        for stage in stages:
            lines.append(_row(
                stage.get("id"), stage.get("title"), ", ".join(_list(stage.get("surfaces"))),
                stage.get("status"), _stage_qa(stage), len(blocking_bugs(stage)),
                _turn(flow.stage_turn(stage)),
            ))
        lines.append("")
    return "\n".join(lines).rstrip("\n") + "\n"


def _automation(scope):
    verification = scope.get("verification") if isinstance(scope.get("verification"), dict) else {}
    return [e for e in _list(verification.get("automation")) if isinstance(e, dict)], verification


def render_coverage(bundle):
    requirements = bundle["requirements"]
    functional = [r for r in requirements if r.get("module") != "NFR" and r.get("status", "active") != "retired"]
    owner, staged = {}, {}
    for feature in bundle["features"]:
        for rid in _list(feature.get("requirements")):
            owner[rid] = feature
    for stage in bundle["stages"]:
        for rid in _list(stage.get("requirements")):
            staged.setdefault(rid, []).append(stage)

    lines = [HEADER, "# Requirement and test coverage", "", "## Summary", "",
             _row("Release", "Requirements", "Owned by a feature", "Assigned to a stage", "Passed QA"),
             _row("---", "---", "---", "---", "---")]
    for release in S.RELEASES:
        scope = [r for r in functional if r.get("release") == release]
        passed = [r for r in scope if any(_passed_qa(s, bundle["features"]) for s in staged.get(r["id"], []))]
        lines.append(_row(
            release, len(scope), sum(1 for r in scope if r["id"] in owner),
            sum(1 for r in scope if r["id"] in staged), len(passed),
        ))

    lines += ["", "## Stages", "",
              "QA runs once, on the whole feature. `Stage QA` shows a result only for a stage pass the owner",
              "asked for; the cases of a stage are written at its feature's pass.", "",
              _row("Stage", "Status", "Stage QA", "Requirements", "Criteria", "Cases", "Automated", "Manual", "Deferred"),
              _row("---", "---", "---", "---", "---", "---", "---", "---", "---")]
    any_stage = False
    for stage in sorted(bundle["stages"], key=lambda s: s.get("id") or ""):
        if stage.get("status") == "outlined":
            continue
        any_stage = True
        entries, verification = _automation(stage)
        automated = set()
        for entry in entries:
            automated.update(_list(entry.get("covers")))
        spec = stage.get("_spec") or {"acs": []}
        lines.append(_row(
            stage.get("id"), stage.get("status"), _stage_qa(stage),
            ", ".join(_list(stage.get("requirements")) + _list(stage.get("nfr_focus"))) or "-",
            len(spec["acs"]), len(_list(stage.get("cases"))), len(automated),
            len(_list(verification.get("manual"))), len(_list(verification.get("deferred"))),
        ))
    if not any_stage:
        lines.append(_row("-", "-", "-", "no stage has been planned yet", "-", "-", "-", "-", "-"))

    lines += ["", "## Deferred cases", "",
              "Cases waiting for something else. `feature-verify` and `release-prepare` go through this list.", "",
              _row("Scope", "Case", "Reason", "Unblocked by"), _row("---", "---", "---", "---")]
    deferred = []
    for scope in sorted(list(bundle["stages"]) + list(bundle["features"]), key=lambda s: s.get("id") or ""):
        for entry in _list(_automation(scope)[1].get("deferred")):
            if isinstance(entry, dict):
                deferred.append(_row(scope.get("id"), entry.get("case"), entry.get("reason"), entry.get("unblocked_by")))
    lines += deferred or [_row("-", "none", "-", "-")]

    lines += ["", "## Requirements", "",
              _row("Requirement", "Release", "Priority", "Feature", "Stages"),
              _row("---", "---", "---", "---", "---")]
    for req in functional:
        feature = owner.get(req["id"])
        stages = ", ".join(f"{s.get('id')} ({s.get('status')})" for s in staged.get(req["id"], []))
        lines.append(_row(
            req["id"], req.get("release"), req.get("priority"),
            feature.get("id") if feature else "unowned", stages or "-",
        ))
    return "\n".join(lines).rstrip("\n") + "\n"


def render(bundle):
    return {
        "features/README.md": render_portfolio(bundle),
        "qa/coverage.md": render_coverage(bundle),
    }
